/** tokens.json -> the CSS custom properties the web app reads (pure, no I/O, so a test can compare it with the committed file). */
const block = (groups, tokens, extra = "") => `:root {\n${extra}${groups.flatMap((g) => Object.entries(tokens[g] || {}).map(([k, v]) => `  --${k}: ${v};\n`)).join("")}}\n`;

export function tokensCss(tokens) {
  return [
    "/* Generated by `npm run tokens` from packages/tokens/tokens.json. Do not edit by hand. */\n",
    block(["color", "chart"], tokens, "  color-scheme: dark;\n"),
    block(["size", "font", "type", "space"], tokens),
    `:root {\n${Object.entries(tokens.elevation || {}).map(([k, v]) => `  --shadow-${k}: ${v};\n`).join("")}}\n`,
  ].join("\n");
}
